package p_cdbf3019a3a300007f3d219dbc66ccf3

import (
 "testing"
 "math/big"
 "math/rand"
 "sync/atomic"
 rt "gopurs/output/gopurs_runtime"
)

var arrayScalarSink int64
var arrayScalarLimit int64 = 900

func arraySelectedLoop(first,last,divisor,residue,seed int64) int64 {
 step:=int64(1)
 if first>last {step=-1}
 for current:=first;;current+=step {
  if rt.IntMod(current,divisor)==residue {seed=rt.IntAdd(seed,current)}
  if current==last{return seed}
 }
}

//go:noinline
func arraySelectedFormula(first,last,divisor,residue,seed int64) int64 {
 if first<1 || last<1 || first>2147483647 || last>2147483647 || seed!=int64(int32(seed)) {
  return arraySelectedLoop(first,last,divisor,residue,seed)
 }
 if first>last {first,last=last,first}
 first+=(residue-first%divisor+divisor)%divisor
 if first>last{return seed}
 count:=(last-first)/divisor+1
 final:=first+(count-1)*divisor
 return int64(int32(seed+count*(first+final)/2))
}

func arrayBigOracle(first,last,divisor,residue,seed int64) int64 {
 if first>last {first,last=last,first}
 begin:=(first+divisor-1-residue)/divisor
 end:=new(big.Int).Div(big.NewInt(last-residue),big.NewInt(divisor)).Int64()
 if end<begin{return seed}
 count:=end-begin+1
 triangular:=func(n int64)*big.Int {x:=new(big.Int).Mul(big.NewInt(n),big.NewInt(n+1));return x.Div(x,big.NewInt(2))}
 indices:=new(big.Int).Sub(triangular(end),triangular(begin-1))
 sum:=new(big.Int).Mul(big.NewInt(divisor),indices)
 sum.Add(sum,new(big.Int).Mul(big.NewInt(count),big.NewInt(residue)))
 sum.Add(sum,big.NewInt(seed))
 return int64(int32(sum.Int64()))
}

func TestArrayScalarPrototype(t *testing.T) {
 rng:=rand.New(rand.NewSource(2187))
 for i:=0;i<10000;i++ {
  first:=int64(rng.Intn(500)+1);last:=int64(rng.Intn(500)+1)
  divisor:=int64(rng.Intn(50)+1);residue:=int64(rng.Intn(int(divisor)));seed:=int64(int32(rng.Uint32()))
  want:=arraySelectedLoop(first,last,divisor,residue,seed)
  for _,got:=range []int64{arraySelectedFormula(first,last,divisor,residue,seed),arrayBigOracle(first,last,divisor,residue,seed)} {
   if got!=want {t.Fatalf("%d %d %d %d %d: got %d want %d",first,last,divisor,residue,seed,got,want)}
  }
 }
 for _,c:=range [][5]int64{
  {1,2147483647,1,0,2147483647},{2147483647,1,1,0,-2147483648},
  {1,2147483647,2,0,17},{2147483647,1,5,3,-2147483648},
  {2147483647,2147483647,2147483647,2147483646,17},
  {2147483647,2147483647,2147483647,0,2147483647},
 } {
  got:=arraySelectedFormula(c[0],c[1],c[2],c[3],c[4]);want:=arrayBigOracle(c[0],c[1],c[2],c[3],c[4])
  if got!=want {t.Fatalf("extreme %v: got %d want %d",c,got,want)}
 }
 for n:=int64(-8);n<3000;n++ {
  got:=Call_Test_ArrayOps_sumEvens(n);want:=arraySelectedFormula(1,n,2,0,0)
  if got!=want {t.Fatalf("generated n=%d got=%d want=%d",n,got,want)}
 }
}

func BenchmarkArrayScalarGenerated(b *testing.B) {
 b.ReportAllocs()
 for i:=0;i<b.N;i++ {arrayScalarSink=Call_Test_ArrayOps_sumEvens(atomic.LoadInt64(&arrayScalarLimit))}
}
func BenchmarkArrayScalarFormula(b *testing.B) {
 b.ReportAllocs()
 for i:=0;i<b.N;i++ {arrayScalarSink=arraySelectedFormula(1,atomic.LoadInt64(&arrayScalarLimit),2,0,0)}
}

